<template>
  <div v-if="auth.token&&!['login','register','setup'].includes(String(route.name))" class="workstation">
    <header class="app-topbar"><router-link class="brand" to="/cases"><span class="brand-mark">AAA</span><span>卷小助</span></router-link><nav class="app-nav"><button data-testid="open-case-history" @click="openHistory">历史案件</button><router-link v-if="auth.isAdmin" to="/settings">设置</router-link><el-dropdown trigger="click"><button class="account-button">{{ auth.user?.display_name||auth.user?.username }} <span>⌄</span></button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="auth.isAdmin" @click="router.push('/admin')">账号管理</el-dropdown-item><el-dropdown-item @click="onLogout">切换使用者</el-dropdown-item></el-dropdown-menu></template></el-dropdown></nav></header>
    <main class="workspace-main"><div v-if="cleanupItems.length" class="case-cleanup-notices"><el-alert v-for="item in cleanupItems" :key="item.caseId" type="warning" :closable="false" data-testid="case-cleanup-notice" :data-case-id="item.caseId" :title="'「'+item.title+'」已删除，工作站文件待清理'"><p>{{ item.error||item.message }}</p><el-button text data-testid="retry-case-cleanup" :loading="item.pending" :disabled="item.pending" @click="cleanupQueue.retry(item.caseId)">重试清理</el-button></el-alert></div><router-view :key="route.path" /></main>
    <el-drawer v-model="historyOpen" title="历史案件" size="min(520px,94vw)" data-testid="case-history" @open="refreshRecentCases"><el-input v-model="historyQuery" placeholder="查找案件" clearable aria-label="查找历史案件" /><p v-if="historyError" class="muted">{{ historyError }} <el-button text @click="refreshRecentCases">重试</el-button></p><div class="history-list"><article v-for="item in filteredCases" :key="item.id" class="history-case" :data-case-id="item.id"><button class="history-case-open" @click="openCase(item)"><strong>{{ item.title }}</strong><span>{{ caseStatus(item) }} · {{ item.file_count||0 }} 份材料</span></button><DeleteCaseButton :case-record="item" /></article><p v-if="!filteredCases.length&&!historyError" class="muted history-empty">{{ historyQuery?'没有匹配的案件':'导入的案件会保留在这里。' }}</p></div></el-drawer>
  </div>
  <router-view v-else />
</template>
<script setup lang="ts">
import { ref,computed,watch,onMounted,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAuthStore } from './stores/auth'
import client from './api/client'
import DeleteCaseButton from './components/DeleteCaseButton.vue'
import { CASES_CHANGED_EVENT,createCaseCleanupQueue } from './domain/caseDeletion.js'
import { caseTaskSummary,caseTaskPresentation } from './domain/taskExperience.js'
const auth=useAuthStore(),route=useRoute(),router=useRouter()
const recentCases=ref<any[]>([]),historyOpen=ref(false),historyQuery=ref(''),historyError=ref(''),cleanupItems=ref<any[]>([])
const filteredCases=computed(()=>recentCases.value.filter(item=>String(item.title).toLowerCase().includes(historyQuery.value.trim().toLowerCase())))
const cleanupQueue=createCaseCleanupQueue({remove:(id:string)=>client.delete('/cases/'+encodeURIComponent(id)),onChange:(items:any[])=>{cleanupItems.value=items},onCleaned:()=>ElMessage.success('工作站文件已清理')})
let recentRequest=0
async function refreshRecentCases(){const request=++recentRequest,token=auth.token;if(!token){recentCases.value=[];return}if(['setup','login','register'].includes(String(route.name)))return;try{const {data}=await client.get('/cases');if(request===recentRequest&&auth.token===token){recentCases.value=data;historyError.value=''}}catch{if(request===recentRequest)historyError.value='暂时无法读取案件，请检查连接。'}}
function onCasesChanged(event:Event){const detail=(event as CustomEvent).detail;if(detail?.action==='deleted'){recentCases.value=recentCases.value.filter(item=>String(item.id)!==String(detail.caseId));cleanupQueue.add(detail)}refreshRecentCases()}
function openHistory(){historyOpen.value=true;refreshRecentCases()}
function openCase(item:any){historyOpen.value=false;router.push(item.last_task_id?'/cases/'+item.id+'/tasks/'+item.last_task_id:'/cases/'+item.id)}
function caseStatus(record:any){return caseTaskPresentation(caseTaskSummary(record)).label}
watch(()=>[route.fullPath,auth.token],refreshRecentCases,{immediate:true})
watch(()=>JSON.stringify([auth.user?.id,auth.user?.org_id,!!auth.token]),()=>{recentRequest++;recentCases.value=[];historyQuery.value='';historyError.value='';cleanupQueue.reset();historyOpen.value=false;refreshRecentCases()})
onMounted(()=>{window.addEventListener(CASES_CHANGED_EVENT,onCasesChanged);window.addEventListener('gd:open-case-history',openHistory);if(auth.token)auth.fetchMe().catch(()=>{})})
onBeforeUnmount(()=>{recentRequest++;cleanupQueue.reset();window.removeEventListener(CASES_CHANGED_EVENT,onCasesChanged);window.removeEventListener('gd:open-case-history',openHistory)})
async function onLogout(){const failure=await router.push('/login');if(!failure)auth.logout()}
</script>
<style>
:root{--el-color-primary:#424245;--el-color-primary-light-3:#6e6e73;--el-color-primary-light-5:#6e6e73;--el-color-primary-light-7:#d2d2d7;--el-color-primary-light-8:#e5e5ea;--el-color-primary-light-9:#f5f5f7;--el-color-primary-dark-2:#424245;--el-color-success:#424245;--el-color-warning:#aa7c3d;--el-border-radius-base:7px;--el-border-color:#e5e5ea;--el-text-color-primary:#1d1d1f;--el-text-color-regular:#424245;--el-fill-color-light:#f5f5f7;--el-font-family:'Microsoft YaHei','PingFang SC',sans-serif}*{box-sizing:border-box}body{margin:0;color:#1d1d1f;background:#fafafa;font-family:var(--el-font-family);font-size:14px;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,textarea{font-family:inherit}.workstation{min-height:100vh}.app-topbar{height:78px;display:flex;align-items:center;justify-content:space-between;gap:24px;max-width:1320px;margin:auto;padding:0 38px;border-bottom:1px solid #f5f5f7}.brand{display:inline-flex;align-items:center;gap:10px;font-size:15px;font-weight:500;color:#424245}.brand-mark{display:grid;place-items:center;width:32px;height:32px;background:#424245;color:#fff;border-radius:10px;font-family:Georgia,serif;font-size:15px}.app-nav{display:flex;align-items:center;gap:26px;font-size:12px;color:#6e6e73}.app-nav>button,.account-button{border:0;background:none;color:inherit;font-size:12px;cursor:pointer;padding:8px 0}.account-button span{margin-left:6px}.workspace-main{max-width:1200px;margin:auto;padding:34px 36px 48px}.history-list{margin-top:22px}.history-case{display:flex;align-items:center;gap:14px;border-bottom:1px solid #f5f5f7;padding:15px 0}.history-case-open{flex:1;min-width:0;border:0;text-align:left;padding:4px;background:none;cursor:pointer}.history-case-open strong{display:block;font-weight:500;font-size:13px;color:#424245;overflow-wrap:anywhere;line-height:1.8}.history-case-open span{display:block;font-size:11px;color:#6e6e73;margin-top:6px}.history-empty{text-align:center;padding:30px 0}.case-cleanup-notices{display:grid;gap:10px;margin-bottom:22px}.case-cleanup-notices p{margin:8px 0 0;line-height:1.8}.page-kicker{font-size:11px;letter-spacing:.15em;color:#6e6e73;margin-bottom:12px}.page-heading{margin:0;font-size:27px;font-weight:500;letter-spacing:.02em;line-height:1.5}.page-description{color:#6e6e73;line-height:1.8;margin:10px 0 24px;font-size:13px}.page-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:28px}.surface{background:#fff;border:1px solid #e5e5ea;border-radius:10px;padding:24px}.section-title{font-size:15px;font-weight:500;margin:0 0 16px}.muted{color:#6e6e73;font-size:12px;line-height:1.8}.back-link{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#6e6e73;margin-bottom:22px}.el-card{box-shadow:none!important;border-color:#e5e5ea}.el-table{--el-table-header-bg-color:#f5f5f7;--el-table-border-color:#f5f5f7;--el-table-row-hover-bg-color:#f5f5f7;background:transparent}.el-table th.el-table__cell{font-weight:500;font-size:12px;color:#6e6e73;height:44px}.el-table td.el-table__cell{height:60px}.el-button{font-weight:400}.el-dialog{border-radius:14px;padding:26px}.el-drawer__header{margin-bottom:12px}.auth-page{min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f5f5f7;padding:24px}.auth-form{width:410px;background:#fff;border:1px solid #e5e5ea;padding:38px;border-radius:14px}.auth-form h1{font-size:25px;font-weight:500;margin:20px 0 7px}.auth-form p{color:#6e6e73;font-size:12px;line-height:1.8;margin-bottom:24px}@media(max-width:720px){.app-topbar{height:64px;padding:0 18px;gap:16px}.app-nav{gap:14px;font-size:11px}.brand{font-size:13px}.brand-mark{width:28px;height:28px}.workspace-main{padding:22px 16px}.page-heading{font-size:22px}.surface{padding:18px}.page-toolbar{flex-wrap:wrap}}
</style>
<style src="./styles/refined.css"></style>


